#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;

    // 关系运算 == 的结果本身就是 bool，可以直接存下来
    bool isEven = (n % 2 == 0);

    // 为什么不能用 n % 2 == 1？因为 C++ 的取余结果跟着被除数走符号：
    // -3 % 2 得到的是 -1 而不是 1，负数奇数会被误判成偶数。
    // 所以判断奇数要用 != 0。
    cout << (isEven ? "even" : "odd") << endl;
    return 0;
}

