#include <iostream>
using namespace std;

int main() {
    int score;
    cin >> score;

    // 从高分往低分写是关键：
    // 走到 else if 时，「比它更高的档」已经被前面的分支排除了，
    // 所以每个分支只写一个下界就够了。
    // 反过来从低往高写（先判 score >= 60），90 分也会落进第一个分支。
    if (score >= 90) {
        cout << "A" << endl;
    } else if (score >= 80) {
        cout << "B" << endl;
    } else if (score >= 70) {
        cout << "C" << endl;
    } else if (score >= 60) {
        cout << "D" << endl;
    } else {
        cout << "E" << endl;
    }
    return 0;
}

