#include <iostream>
using namespace std;

int main() {
    int year;
    cin >> year;

    // 口诀：四年一闰，百年不闰，四百年再闰。
    // 整个条件 =（能被 4 整除 且 不能被 100 整除）或（能被 400 整除）
    // && 的优先级比 || 高，不加括号其实也是这个意思，
    // 但括号照写不误：让读代码的人一眼看出哪两个条件是一组。
    bool leap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);

    // leap 本身就是 bool，三元运算符直接拿它当条件
    cout << (leap ? "Yes" : "No") << endl;
    return 0;
}

