int big = (a > b) ? a : b;
cout << big << endl;

int a = 2, b = 5, c = 9;
int mx = (a > b) ? a : b;    // 2 和 5 比 → 5
mx = (mx > c) ? mx : c;      // 5 和 9 比 → 9
cout << mx << endl;

