#include <iostream>
using namespace std;

int main() {
    int year, month;
    cin >> year >> month;

    int days = 0;
    switch (month) {
        // 大月：1、3、5、7、8、10、12 全都是 31 天。
        // 这里「故意」不写 break —— 几个 case 叠在一起共用下面这段代码，
        // 是 switch 穿透的正确用法（记得写注释说明是故意的）。
        case 1: case 3: case 5: case 7:
        case 8: case 10: case 12:
            days = 31;
            break;
        // 小月
        case 4: case 6: case 9: case 11:
            days = 30;
            break;
        case 2:
            // 2 月是唯一随年份变化的月份，闰年条件不能省括号
            days = ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) ? 29 : 28;
            break;
        default:
            days = 0;   // 题目保证 month 在 1~12，这里只是兜底
    }

    cout << days << endl;
    return 0;
}

