#include <iostream>
using namespace std;

int main() {
    int a, b, c;
    cin >> a >> b >> c;

    // 先把「能不能构成」这个结论算出来存进 bool，下面读起来清爽很多。
    // 三条边要两两之和都大于第三边；注意是 > 不是 >=，
    // 1、2、3 这种「压扁成一条直线」的不算三角形。
    bool triangle = (a + b > c) && (a + c > b) && (b + c > a);

    if (!triangle) {
        cout << "No" << endl;
    } else {
        cout << "Yes" << endl;

        // 先判等边：5 5 5 同样满足「有两边相等」，
        // 顺序反了就会被误判成 isosceles。
        if (a == b && b == c) {
            cout << "equilateral" << endl;
        } else if (a == b || b == c || a == c) {
            // 任意一对相等就算等腰，只写 a == b 会漏掉 5 8 5 这种输入
            cout << "isosceles" << endl;
        } else {
            cout << "scalene" << endl;
        }
    }
    return 0;
}

tutorial.body:
这道题有两个层次的问题：「是不是三角形」和「是哪一种三角形」。第二问只有在第一问成立时才有意义，所以要用**嵌套**：

```
if (!triangle) {
    cout << "No" << endl;
} else {
    // 这里已经确定是三角形了，再判类型
    ...
}
```

`!` 是逻辑非，`!triangle` 读作「不是三角形」。

如果不嵌套，把类型判断和三角形判断平铺成一条 else if 链，就会出现「边长不合法却照样输出 isosceles」的情况。**嵌套的意义就是把前提锁死**：外层条件不成立，内层代码根本不会被执行。

写嵌套的时候注意缩进——每层往里缩 4 个空格，代码的层次结构一眼可见。缩进乱掉的嵌套代码是最难读的。

