if (!triangle) {
    cout << "No" << endl;
} else {
    cout << "Yes" << endl;   // 只有确定是三角形才走到这里
}

int a = 5, b = 8, c = 5;
if (a == b || b == c || a == c) cout << "isosceles" << endl;
else cout << "scalene" << endl;
